head.script:
scwin.__isShowLogNormal = function() {
    var err = WebSquare.logger.getErrorLog();
    return !err;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. IE6, IE7, IE8, IE9에서 샘플파일을 실행 후 로그보기를 통해 오류가 있는지 확인한다.
    //1. Execute the sample file in IE6, IE7, IE8, IE9 and check the log to see if there is an error.
    //WebSquare.wUnit.addCommand("set", "");
    // verify step 1. IE6, IE7, IE8, IE9에서 로그오류가 보여지지 않는다.(이전에는 '잘못된 인수입니다.'라는 오류가 보여짐)
    //1. Log errors are not shown in IE6, IE7, IE8, IE9 (Previously there was an 'invalid argument' error)
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowLogNormal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
